Here are both approaches for .NET MAUI Shell navigation:

## Approach 1: Pass Product ID as a query parameter

```csharp
// ProductListPage.xaml.cs or ViewModel command
async void OnProductSelected(Product product)
{
    await Shell.Current.GoToAsync($"{nameof(ProductDetailsPage)}?productId={product.Id}");
}
```

## Approach 2: Pass the full object via navigation parameters

```csharp
async void OnProductSelected(Product product)
{
    var navParams = new Dictionary<string, object>
    {
        { "product", product }
    };
    await Shell.Current.GoToAsync(nameof(ProductDetailsPage), navParams);
}
```

## Receiving data with IQueryAttributable

```csharp
public class ProductDetailsViewModel : ObservableObject, IQueryAttributable
{
    private readonly IProductService _productService;

    public ProductDetailsViewModel(IProductService productService)
    {
        _productService = productService;
    }

    public Product Product { get; private set; }

    public void ApplyQueryAttributes(IDictionary<string, object> query)
    {
        // Approach 1: receive the ID string, then load the product
        if (query.TryGetValue("productId", out var idObj) && idObj is string id)
        {
            LoadProduct(id);
        }

        // Approach 2: receive the full object directly
        if (query.TryGetValue("product", out var obj) && obj is Product product)
        {
            Product = product;
            OnPropertyChanged(nameof(Product));
        }
    }

    private async void LoadProduct(string productId)
    {
        Product = await _productService.GetProductAsync(productId);
        OnPropertyChanged(nameof(Product));
    }
}
```

## Wire up the ViewModel on the page

```csharp
public partial class ProductDetailsPage : ContentPage
{
    public ProductDetailsPage(ProductDetailsViewModel vm)
    {
        InitializeComponent();
        BindingContext = vm;
    }
}
```

## Route registration (in AppShell or MauiProgram)

```csharp
Routing.RegisterRoute(nameof(ProductDetailsPage), typeof(ProductDetailsPage));
```

**Key differences:**

| | Query string | Dictionary (object) |
|---|---|---|
| Data type | Strings only | Any object |
| Survives serialization | Yes (deep-link safe) | No |
| Use when | Simple IDs, deep links | Complex objects already in memory |

Both arrive in the same `ApplyQueryAttributes` method — the dictionary just carries either a parsed string or the actual object reference.
